public static int countDoubles(int[] numbers) {
    // Build frequency map of all numbers
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : numbers) {
        freq.put(num, freq.getOrDefault(num, 0) + 1);
    }

    int count = 0;
    for (int num : numbers) {
        // Only even numbers can be twice another integer
        if (num % 2 == 0) {
            int half = num / 2;
            Integer halfCount = freq.get(half);
            if (halfCount != null) {
                if (half == num) {
                    // num is zero or any number where half equals num
                    // Need at least two occurrences to be "some other item"
                    if (halfCount > 1) {
                        count++;
                    }
                } else {
                    count++;
                }
            }
        }
    }
    return count;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();
    for (int[] p : paths) {
        if (p.length < 4) continue;
        String a = p[0] + "," + p[1];
        String b = p[2] + "," + p[3];
        adj.computeIfAbsent(a, k -> new java.util.ArrayList<>()).add(b);
        adj.computeIfAbsent(b, k -> new java.util.ArrayList<>()).add(a);
    }
    String startKey = start[0] + "," + start[1];
    String endKey = end[0] + "," + end[1];
    if (startKey.equals(endKey)) return "can be travelled";
    java.util.Set<String> visited = new java.util.HashSet<>();
    java.util.Queue<String> queue = new java.util.LinkedList<>();
    queue.add(startKey);
    visited.add(startKey);
    while (!queue.isEmpty()) {
        String cur = queue.poll();
        java.util.List<String> neighbors = adj.get(cur);
        if (neighbors == null) continue;
        for (String nb : neighbors) {
            if (!visited.contains(nb)) {
                if (nb.equals(endKey)) return "can be travelled";
                visited.add(nb);
                queue.add(nb);
            }
        }
    }
    return "cannot be travelled";
}

