public boolean canArrange(int[] arr, int k) {
    if (arr == null || k <= 0) return false;
    int n = arr.length;
    if (n % 2 != 0) return false; // must be even length to form pairs
    int[] count = new int[k];
    for (int num : arr) {
        int r = num % k;
        if (r < 0) r += k;
        count[r]++;
    }
    // remainder 0 must be even
    if (count[0] % 2 != 0) return false;
    // if k is even, remainder k/2 must also be even
    if (k % 2 == 0) {
        if (count[k / 2] % 2 != 0) return false;
    }
    // for other remainders, counts must match complementary remainders
    for (int r = 1; r < k; r++) {
        if (r == k - r) continue; // already handled for k even
        if (count[r] != count[k - r]) return false;
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] degree = new int[n];
    for (int[] e : edges) {
        degree[e[0]]++;
        degree[e[1]]++;
    }
    int[][] graph = new int[n][];
    for (int i = 0; i < n; i++) {
        graph[i] = new int[degree[i]];
    }
    int[] idx = new int[n];
    for (int[] e : edges) {
        int u = e[0], v = e[1];
        graph[u][idx[u]++] = v;
        graph[v][idx[v]++] = u;
    }
    int[] time = new int[1];
    dfs(0, -1, graph, hasApple, time);
    return time[0];
}

private boolean dfs(int node, int parent, int[][] graph, boolean[] hasApple, int[] time) {
    boolean has = hasApple[node];
    for (int nei : graph[node]) {
        if (nei == parent) continue;
        boolean childHas = dfs(nei, node, graph, hasApple, time);
        if (childHas) {
            time[0] += 2;
            has = true;
        }
    }
    return has;
}

public String sortString(String s) {
    int[] freq = new int[26];
    for (char c : s.toCharArray()) {
        freq[c - 'a']++;
    }
    StringBuilder sb = new StringBuilder();
    int total = s.length();
    while (sb.length() < total) {
        for (int i = 0; i < 26; i++) {
            if (freq[i] > 0) {
                sb.append((char) (i + 'a'));
                freq[i]--;
            }
        }
        for (int i = 25; i >= 0; i--) {
            if (freq[i] > 0) {
                sb.append((char) (i + 'a'));
                freq[i]--;
            }
        }
    }
    return sb.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;
    int totalSum = 0;
    for (int num : nums) totalSum += num;
    int maxK = n / 2;
    java.util.Set<Integer>[] dp = new java.util.HashSet[n + 1];
    for (int i = 0; i <= n; i++) dp[i] = new java.util.HashSet<>();
    dp[0].add(0);
    for (int num : nums) {
        for (int k = Math.min(maxK, n); k >= 1; k--) {
            for (int sum : dp[k - 1]) {
                dp[k].add(sum + num);
            }
        }
    }
    for (int k = 1; k <= maxK; k++) {
        if ((totalSum * k) % n != 0) continue;
        int target = (totalSum * k) / n;
        if (dp[k].contains(target)) return true;
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];
    int prev2 = 0; // cost to reach step 0
    int prev1 = 0; // cost to reach step 1
    for (int i = 2; i <= n; i++) {
        int current = cost[i - 1] + Math.min(prev1, prev2);
        prev2 = prev1;
        prev1 = current;
    }
    return prev1;
}

