public boolean hasAllCodes(String s, int k) {
    int n = s.length();
    int total = 1 << k; // total number of binary strings of length k
    if (n < total) return false;

    boolean[] seen = new boolean[total];
    int mask = total - 1;
    int code = 0;

    // Build initial code for first k characters
    for (int i = 0; i < k; i++) {
        code = (code << 1) | (s.charAt(i) - '0');
    }
    seen[code] = true;
    int count = 1;

    // Slide over the string
    for (int i = k; i < n; i++) {
        code = ((code << 1) | (s.charAt(i) - '0')) & mask;
        if (!seen[code]) {
            seen[code] = true;
            count++;
            if (count == total) return true; // early exit
        }
    }
    return count == total;
}

