}

private void dfs(String s, int idx, java.util.HashSet<String> used, int[] max) {
    if (idx == s.length()) {
        if (used.size() > max[0]) {
            max[0] = used.size();
        }
        return;
    }
    for (int end = idx + 1; end <= s.length(); end++) {
        String sub = s.substring(idx, end);
        if (!used.contains(sub)) {
            used.add(sub);
            dfs(s, end, used, max);
            used.remove(sub);
        }
    }
}

