public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    int[][] horizontal = new int[m][n];
    int[][] vertical = new int[m][n];
    int[][] diagonal = new int[m][n];
    int[][] antiDiagonal = new int[m][n];
    int max = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                horizontal[i][j] = (j > 0 ? horizontal[i][j - 1] : 0) + 1;
                vertical[i][j] = (i > 0 ? vertical[i - 1][j] : 0) + 1;
                diagonal[i][j] = (i > 0 && j > 0 ? diagonal[i - 1][j - 1] : 0) + 1;
                antiDiagonal[i][j] = (i > 0 && j < n - 1 ? antiDiagonal[i - 1][j + 1] : 0) + 1;
                int localMax = Math.max(
                        Math.max(horizontal[i][j], vertical[i][j]),
                        Math.max(diagonal[i][j], antiDiagonal[i][j]));
                if (localMax > max) {
                    max = localMax;
                }
            } else {
                horizontal[i][j] = 0;
                vertical[i][j] = 0;
                diagonal[i][j] = 0;
                antiDiagonal[i][j] = 0;
            }
        }
    }
    return max;
}

public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }
    boolean negative = n < 0;
    long num = Math.abs((long) n);
    StringBuilder sb = new StringBuilder();
    int count = 0;
    while (num > 0) {
        sb.append(num % 10);
        num /= 10;
        count++;
        if (num > 0 && count % 3 == 0) {
            sb.append('.');
        }
    }
    if (negative) {
        sb.append('-');
    }
    return sb.reverse().toString();
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    int max = 0;
    for (int v : A) if (v > max) max = v;
    int maxSum = max * 2;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int i = 0; i * i <= maxSum; i++) isSquare[i * i] = true;
    java.util.Arrays.sort(A);
    int[][] dp = new int[1 << n][n + 1];
    for (int i = 0; i < dp.length; i++) java.util.Arrays.fill(dp[i], -1);
    long res = dfs(0, -1, A, dp, isSquare);
    return (int) res;
}

private static long dfs(int mask, int last, int[] A, int[][] dp, boolean[] isSquare) {
    int n = A.length;
    if (mask == (1 << n) - 1) return 1;
    int idx = last + 1;
    if (dp[mask][idx] != -1) return dp[mask][idx];
    long total = 0;
    for (int i = 0; i < n; i++) {
        if ((mask & (1 << i)) != 0) continue;
        if (last != -1 && !isSquare[A[last] + A[i]]) continue;
        if (i > 0 && A[i] == A[i - 1] && (mask & (1 << (i - 1))) == 0) continue;
        total += dfs(mask | (1 << i), i, A, dp, isSquare);
    }
    dp[mask][idx] = (int) total;
    return total;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int n = heights.length;
    int[] stack = new int[n];
    int top = -1;
    int maxArea = 0;
    for (int i = 0; i <= n; i++) {
        int currentHeight = (i == n) ? 0 : heights[i];
        while (top >= 0 && currentHeight < heights[stack[top]]) {
            int height = heights[stack[top--]];
            int width = (top == -1) ? i : i - stack[top] - 1;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack[++top] = i;
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int idx = 0;
    for (int sum = 0; sum < m + n - 1; sum++) {
        if (sum % 2 == 0) {
            int i = Math.min(sum, m - 1);
            int j = sum - i;
            while (i >= 0 && j < n) {
                result[idx++] = mat[i][j];
                i--;
                j++;
            }
        } else {
            int j = Math.min(sum, n - 1);
            int i = sum - j;
            while (j >= 0 && i < m) {
                result[idx++] = mat[i][j];
                i++;
                j--;
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    char[] digits = String.valueOf(n).toCharArray();
    int len = digits.length;
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        return -1;
    }
    int j = len - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    int left = i + 1, right = len - 1;
    while (left < right) {
        char t = digits[left];
        digits[left] = digits[right];
        digits[right] = t;
        left++;
        right--;
    }
    try {
        return Integer.parseInt(new String(digits));
    } catch (NumberFormatException e) {
        return -1;
    }
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    char[] digits = {'0', '1', '8', '6', '9'};
    char[][] mirror = {
        {'0', '0'}, // 0 -> 0
        {'1', '1'}, // 1 -> 1
        {'8', '8'}, // 8 -> 8
        {'6', '9'}, // 6 -> 9
        {'9', '6'}  // 9 -> 6
    };
    char[] arr = new char[n];
    int half = n / 2;

    java.util.function.Consumer<Integer> dfs = new java.util.function.Consumer<Integer>() {
        @Override
        public void accept(Integer pos) {
            if (pos == half) {
                if (n % 2 == 1) {
                    for (char mid : new char[]{'0', '1', '8'}) {
                        arr[half] = mid;
                        result.add(new String(arr));
                    }
                } else {
                    result.add(new String(arr));
                }
                return;
            }
            for (char d : digits) {
                arr[pos] = d;
                // find mirror of d
                char m = d;
                for (char[] pair : mirror) {
                    if (pair[0] == d) {
                        m = pair[1];
                        break;
                    }
                }
                arr[n - 1 - pos] = m;
                accept(pos + 1);
            }
        }
    };

    dfs.accept(0);
    return result;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    // Ensure all points are distinct
    for (int i = 0; i < 3; i++) {
        for (int j = i + 1; j < 3; j++) {
            if (points[i][0] == points[j][0] && points[i][1] == points[j][1]) {
                return false;
            }
        }
    }
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];
    // Compute cross product to check collinearity
    int cross = (x2 - x1) * (y3 - y1) - (y2 - y1) * (x3 - x1);
    return cross != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer.");
    }
    int[] ugly = new int[n];
    ugly[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    int next2 = 2, next3 = 3, next5 = 5;
    for (int i = 1; i < n; i++) {
        int nextUgly = Math.min(next2, Math.min(next3, next5));
        ugly[i] = nextUgly;
        if (nextUgly == next2) {
            i2++;
            next2 = ugly[i2] * 2;
        }
        if (nextUgly == next3) {
            i3++;
            next3 = ugly[i3] * 3;
        }
        if (nextUgly == next5) {
            i5++;
            next5 = ugly[i5] * 5;
        }
    }
    return ugly[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int maxLen = 1;
    int currentLen = 1;
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentLen++;
        } else {
            if (currentLen > maxLen) {
                maxLen = currentLen;
            }
            currentLen = 1;
        }
    }
    if (currentLen > maxLen) {
        maxLen = currentLen;
    }
    return maxLen;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> res = new ArrayList<>();
    for (int i = 1; i <= 9; i++) {
        dfs(i, n, res);
    }
    return res;
}

private static void dfs(int curr, int n, List<Integer> res) {
    if (curr > n) return;
    res.add(curr);
    for (int i = 0; i <= 9; i++) {
        long next = (long) curr * 10 + i;
        if (next > n) break;
        dfs((int) next, n, res);
    }
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    java.util.Map<Integer, Integer> countMap = new java.util.HashMap<>();
    for (int num : nums) {
        countMap.put(num, countMap.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : countMap.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    // Initialize with a large number
    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
    }
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            if (dp[i - square] + 1 < dp[i]) {
                dp[i] = dp[i - square] + 1;
            }
        }
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    StringBuilder word = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == ' ') {
            result.append(word.reverse());
            word.setLength(0);
            result.append(' ');
        } else {
            word.append(c);
        }
    }
    result.append(word.reverse());
    return result.toString();
}
